"""Build a printable source-only review guide and blank CSV from the frozen cases.
Does not read proposed reference labels or predictions. Uses Python standard library.
"""
from pathlib import Path
import csv,html,json
ROOT=Path(__file__).resolve().parents[1];DEST=ROOT/'dist/validation'
cases=json.loads((DEST/'cases.json').read_text())['cases']
esc=html.escape
rubric=[('Matching instructions','Written amounts (including equivalent SI units), route, and frequency agree where mentioned.'),('Documented change','An explicit change or restart explains the transition, without an earlier unresolved discrepancy.'),('Unexplained discrepancy','Instructions disagree without an adequate explanation, or disagree on the same date with unknown order.'),('Missing from latest record','The medicine is omitted from a latest record without an applicable explicit stop. Omission is not discontinuation.'),('Explicit stop documented','The latest target-specific instruction is an explicit stop, with no later restart or unresolved discrepancy.'),('First documented','First mention in the supplied records; actual treatment start date is unknown.'),('Insufficient evidence','Dates, missing fields, or ambiguous/conditional instructions prevent a supported judgment. Clear wording is not unresolved just because software cannot parse it.')]
parts=['''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MedDelta — Reviewer guide and fictional packets</title><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="lab.css"></head><body><main class="guide-main"><a class="text-button no-print" href="../validation.html">← Validation lab</a><div class="eyebrow" style="margin-top:25px">SOURCE-ONLY REVIEW PACK · PROTOCOL 1</div><h1>Review the evidence first.</h1><p>MedDelta temporal dataset v1 · 32 fictional packets · 29 October 2026</p><div class="notice"><strong>Pharmacist review is pending.</strong><p>These developer-authored examples are software research material, not patient records or treatment guidance. All medicine names are fictional. Judge what the documents support, not whether treatment is suitable.</p></div><h2>How to review</h2><ol><li>Read the rubric below. Start with the eight practice packets to clarify definitions.</li><li>For each evaluation packet, choose one label, cite source lines or document dates, and explain your reasoning and uncertainty.</li><li>Complete evaluation judgments before viewing MedDelta predictions, developer reference labels, or prior reviews.</li><li>Export your review JSON from the lab. You can reopen it to resume. Browser work disappears on reload.</li><li>After completing the evaluation set, compare predictions and record disagreements. Changes made after exposure must remain distinguishable from the initial judgments.</li></ol><p>Document dates order evidence. A later explicit change does not automatically resolve an earlier unexplained discrepancy. Missing mention never implies a stop. An explicit stop is a documentary finding, not a treatment recommendation. Line 0 refers to the document date.</p><p>Names, reviewer roles, and timestamps are self-entered or browser-generated. This workflow does not authenticate clinicians or prevent prior exposure outside the app.</p><p class="no-print"><a class="text-button" href="review-pack.pdf" download>Download printable review pack PDF ↓</a></p><p class="no-print">Use your browser's Print command for a paper copy. <a class="text-button" href="blank-review.csv" download>Download blank review CSV ↓</a> (for manual use; the app reopens its own JSON exports).</p><h2>Label rubric</h2><table><thead><tr><th>Label</th><th>Meaning</th></tr></thead><tbody>''']
parts += [f'<tr><td>{esc(label)}</td><td>{esc(meaning)}</td></tr>' for label,meaning in rubric]
parts.append('</tbody></table><h2>Source packets</h2><p>No predictions or proposed labels are included below. Cite the records and lines used for each judgment.</p>')
for c in cases:
 parts.append(f'<section class="review-packet"><h2>{c["id"]} · {esc(c["target"])} · {c["split"]}</h2>')
 for r in c['records']:
  parts.append(f'<h3>{esc(r["title"])} ({esc(r["id"])})</h3><p>Line 0 — Document date: {esc(r["date"] or "(missing)")}</p>')
  parts.extend(f'<p>{i+1}. {esc(line)}</p>' for i,line in enumerate(r['text'].split('\n')))
 parts.append('<p>Judgment: ____________________<br>Evidence (record IDs and lines): ____________________<br>Reasoning / uncertainty: ____________________________________________________</p></section>')
parts.append('</main></body></html>')
(DEST/'reviewer-guide.html').write_text('\n'.join(parts)+'\n')
with (DEST/'blank-review.csv').open('w',newline='') as f:
 writer=csv.writer(f,lineterminator="\n");writer.writerow(['case_id','split','target','label','evidence_record_ids_and_lines','reasoning','reviewer','self_reported_role'])
 for c in cases:writer.writerow([c['id'],c['split'],c['target'],'','','','',''])
print('Built source-only printable guide and 32-row blank review CSV.')
